import type * as Stitches from "@stitches/react";

import { styled, CSS } from "../../../stitches.config";
import { colorVariants } from "../../utils/color-variants";

const sizeTokens = {
  inherit: { $$width: "auto", $$height: "auto" },
  xs: { $$width: "$fontSizes$3", $$height: "$fontSizes$3" },
  sm: { $$width: "$space$sm", $$height: "$space$sm" },
  md: { $$width: "$space$md", $$height: "$space$md" },
  lg: { $$width: "$space$lg", $$height: "$space$lg" },
  xl: { $$width: "$space$xl", $$height: "$space$xl" },
  "2xl": { $$width: "$space$2xl", $$height: "$space$2xl" },
  "3xl": { $$width: "$space$3xl", $$height: "$space$3xl" },
} as const;

export const SvgIcon = styled("svg", {
  $$width: "1em",
  $$height: "1em",
  $$color: "$colors$black",
  lineHeight: "1em",
  verticalAlign: "middle",
  width: "$$width",
  height: "$$height",
  variants: {
    color: {
      inherit: {
        $$color: "currentColor",
      },
      ...colorVariants,
    },
    /** Sets both width and height to the same token value (square icons). */
    size: sizeTokens,
    /**
     * Overrides only the width. Define after `size` so it wins when combined:
     * `<SvgIcon size="md" width="xl" />` → width=xl, height=md.
     */
    width: {
      inherit: { $$width: "auto" },
      xs: { $$width: "$fontSizes$3" },
      sm: { $$width: "$space$sm" },
      md: { $$width: "$space$md" },
      lg: { $$width: "$space$lg" },
      xl: { $$width: "$space$xl" },
      "2xl": { $$width: "$space$2xl" },
      "3xl": { $$width: "$space$3xl" },
    },
    /** Overrides only the height. Same cascade precedence note as `width`. */
    height: {
      inherit: { $$height: "auto" },
      xs: { $$height: "$fontSizes$3" },
      sm: { $$height: "$space$sm" },
      md: { $$height: "$space$md" },
      lg: { $$height: "$space$lg" },
      xl: { $$height: "$space$xl" },
      "2xl": { $$height: "$space$2xl" },
      "3xl": { $$height: "$space$3xl" },
    },
    fillColor: {
      true: {
        "& path": {
          fill: "$$color",
        },
      },
      false: {
        "& path": {
          fill: "none",
        },
      },
    },
    strokeColor: {
      true: {
        "& path": {
          stroke: "$$color",
        },
      },
      false: {
        "& path": {
          stroke: "none",
        },
      },
    },
    transform: {
      xAxis: {
        transform: "scale(-1)",
      },
    },
  },
  defaultVariants: {
    size: "sm",
    color: "inherit",
    fillColor: "default",
    strokeColor: "default",
  },
});

// React 19 still applies defaultProps to forwardRef components (which Stitches
// styled() returns), but @types/react 19 no longer declares the property.
Object.assign(SvgIcon, {
  defaultProps: {
    viewBox: "0 0 16 16",
    preserveAspectRatio: "none",
    fill: "none",
    xmlns: "http://www.w3.org/2000/svg",
  },
});

export type SvgIconProps = {
  css?: CSS;
} & Stitches.VariantProps<typeof SvgIcon>;
