/**
 * Visible keyboard focus for interactive components. Several primitives use
 * `all: "unset"` or `outline: "none"`, which removes the browser's ring; this
 * :focus-visible rule is more specific, so it wins without touching those.
 */
export const focusRing = {
  "&:focus-visible": {
    outline: "2px solid $obolGreen",
    outlineOffset: "2px",
  },
} as const;

/** Strips native <button> chrome so a Box/Flex rendered `as="button"` keeps its look. */
export const buttonReset = {
  appearance: "none",
  margin: 0,
  padding: 0,
  border: "none",
  background: "none",
  font: "inherit",
  color: "inherit",
  textAlign: "inherit",
  cursor: "pointer",
  ...focusRing,
} as const;

